package io.github.hoangtnedu.java;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.math.BigDecimal;import java.util.*;
public class App {
 public static JFrame window(ShopService service){JFrame f=new JFrame("HoangTN - MiniShop");JTabbedPane tabs=new JTabbedPane();
  tabs.add("San pham",crud(service,true));tabs.add("Khach hang",crud(service,false));
  JTextField customer=new JTextField(6),product=new JTextField(6),quantity=new JTextField("1",4);JLabel invoiceResult=new JLabel();JButton sell=new JButton("Luu hoa don");JPanel invoice=new JPanel();invoice.add(new JLabel("Ma KH / Ma SP / So luong"));invoice.add(customer);invoice.add(product);invoice.add(quantity);invoice.add(sell);invoice.add(invoiceResult);sell.addActionListener(e->background(sell,()->service.invoice(Long.parseLong(customer.getText()),Map.of(Long.parseLong(product.getText()),Integer.parseInt(quantity.getText()))),x->invoiceResult.setText("Hoa don: "+x)));tabs.add("Hoa don",invoice);
  DefaultTableModel stats=new DefaultTableModel(new Object[]{"Ngay","Doanh thu"},0);JPanel report=new JPanel(new BorderLayout());JButton load=new JButton("Thong ke bang SwingWorker");load.addActionListener(e->background(load,service::revenue,x->{stats.setRowCount(0);x.forEach(stats::addRow);}));report.add(load,BorderLayout.NORTH);report.add(new JScrollPane(new JTable(stats)));tabs.add("Thong ke",report);f.add(tabs);f.setSize(950,500);f.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);return f;
 }
 private static JPanel crud(ShopService s,boolean product){JPanel p=new JPanel(new BorderLayout());JTextField id=new JTextField(4),name=new JTextField(12),a=new JTextField(8),b=new JTextField(10),q=new JTextField(8);JPanel top=new JPanel();top.add(new JLabel(product?"Ma/Ten/Gia/Ton":"Ma/Ten/SDT/Dia chi"));for(var x:new JTextField[]{id,name,a,b,q})top.add(x);DefaultTableModel m=new DefaultTableModel(product?new Object[]{"Ma","Ten","Gia","Ton"}:new Object[]{"Ma","Ten","SDT","Dia chi"},0);JTable table=new JTable(m);p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(table));JPanel buttons=new JPanel();
  for(String action:new String[]{"Them","Sua","Xoa","Tai/Tim"}){JButton button=new JButton(action);buttons.add(button);button.addActionListener(e->background(button,()->{if(action.equals("Them")){if(product)s.product(name.getText(),new BigDecimal(a.getText()),Integer.parseInt(b.getText()));else s.customer(name.getText(),a.getText(),b.getText());}else if(action.equals("Sua")){if(product)s.editProduct(Long.parseLong(id.getText()),name.getText(),new BigDecimal(a.getText()),Integer.parseInt(b.getText()));else s.editCustomer(Long.parseLong(id.getText()),name.getText(),a.getText(),b.getText());}else if(action.equals("Xoa")){if(product)s.deleteProduct(Long.parseLong(id.getText()));else s.deleteCustomer(Long.parseLong(id.getText()));}return product?s.products(q.getText()):s.customers();},rows->{m.setRowCount(0);rows.forEach(m::addRow);}));}p.add(buttons,BorderLayout.SOUTH);return p;}
 private interface Work<T>{T call()throws Exception;}
 private static <T>void background(JButton button,Work<T> work,java.util.function.Consumer<T> done){button.setEnabled(false);new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return work.call();}protected void done(){try{done.accept(get());}catch(Exception ex){JOptionPane.showMessageDialog(button,ex.getCause()==null?ex.getMessage():ex.getCause().getMessage());}finally{button.setEnabled(true);}}}.execute();}
 public static void main(String[] args)throws Exception{ShopDao dao=new ShopDao();dao.init();SwingUtilities.invokeLater(()->window(new ShopService(dao)).setVisible(true));}
}